"""Exact algebra/group generated by declared P projectors and proper rotations."""
from pathlib import Path
from itertools import product as pairs
import contextlib,io,json,hashlib
with contextlib.redirect_stdout(io.StringIO()):
    import check_rotation_realization_square as s
A,I,ONE,ZERO=s.A,s.I,s.ONE,s.ZERO
mul,add,scale=s.product,s.plus,s.scaled
L,G,N=(s.r.Pop[k] for k in ['L','G','N'])
assert mul(L,G)==mul(G,L)==N
sectors=[N,add(L,scale(A(-1),N)),add(G,scale(A(-1),N)),add(I,scale(A(-1),L),scale(A(-1),G),N)]
assert add(*sectors)==I
ranks=[1,11,2,22]
for i,P in enumerate(sectors):
    assert P and s.adjoint(P)==P
    assert sum((x for (a,b),x in P.items() if a==b),ZERO)==A(ranks[i])
    for j,Q in enumerate(sectors):assert mul(P,Q)==(P if i==j else {})
RL,RG=add(scale(A(2),L),scale(A(-1),I)),add(scale(A(2),G),scale(A(-1),I))
assert mul(RL,RL)==mul(RG,RG)==I
assert s.adjoint(RL)==RL and s.adjoint(RG)==RG
assert mul(RL,RG)==mul(RG,RL)
refs={(0,0):I,(1,0):RL,(0,1):RG,(1,1):mul(RL,RG)}
for (a,b),X in refs.items():
    for (c,d),Y in refs.items():assert mul(X,Y)==refs[a^c,b^d]
U=s.targetActions
assert len(U)==12 and s.compositions==144
# Independent even vertex permutations supply A4; no fitted conjugate action.
assert all(sum(g[i]>g[j] for i in range(4) for j in range(i+1,4))%2==0 for g in U)
for rotation in U.values():
    assert mul(rotation,RL)==mul(RL,rotation)
    assert mul(rotation,RG)==mul(RG,rotation)
def token(matrix):
    return json.dumps([[i,j,x.record()] for (i,j),x in sorted(matrix.items())],sort_keys=True)
matrices={(g,a,b):mul(rotation,ref) for g,rotation in U.items() for (a,b),ref in refs.items()}
assert len(matrices)==len({token(m) for m in matrices.values()})==48
# Full group table certified by the checked factor tables and commutation.
# Not 2304 fresh dense matrix products: the factorization is the certificate.
def compose(x,y):
    g,a,b=x;h,c,d=y
    return tuple(g[h[i]] for i in range(4)),a^c,b^d
keys=list(matrices);identity=((0,1,2,3),0,0)
table=[[keys.index(compose(x,y)) for y in keys] for x in keys]
assert all(compose(x,identity)==compose(identity,x)==x for x in keys)
assert all(any(compose(x,y)==compose(y,x)==identity for y in keys) for x in keys)
assert all(compose(compose(x,y),z)==compose(x,compose(y,z)) for x,y,z in pairs(keys,repeat=3))
orders={}
for x in keys:
    current=identity
    for order in range(1,49):
        current=compose(current,x)
        if current==identity:break
    else:raise AssertionError('no finite order')
    orders[order]=orders.get(order,0)+1
assert orders=={1:1,2:15,3:8,6:24}
ROOT=Path(__file__).resolve().parents[3];BASE=ROOT/'research/strominger/results'
result={'status':'pass','classification':'declared-simplex-operation-group-A4-times-Klein-four',
        'projectorAlgebra':{'isomorphism':'C^4','dimension':4,'jointSectorRanks':ranks,'products':'E_i E_j = delta_ij E_i','sum':'I36'},
        'derivedReflections':{'definitions':['2L-I','2G-I'],'group':'C2 x C2','order':4,'metricUnitary':True,'nativeMovePermission':False},
        'combinedGroup':{'isomorphism':'A4 x C2 x C2','order':48,'distinctExactMatrices':48,'elementOrderCounts':orders,'factorCompositionChecks':{'rotations':144,'reflections':16,'commutations':24},'compositionTableSize':[48,48],'closureCertificate':'Checked factor matrices plus commuting factors and48 distinct resulting matrices; full factored table associativity checked.'},
        'associativeOperatorAlgebra':{'spanningMatrices':48,'dimensionUpperBound':48,'exactDimensionComputed':False,'product':'ordinary associative matrix composition, not a supplied Griess product'},
        'monsterIdentified':False,'babyMonsterIdentified':False,'canonicalParentConstructed':False,
        'scope':'Only the declared P projector reflections and independent proper tetrahedral actions. Not all possible interface operations or automorphisms. Co-moving rigid translation acts trivially on this fiber, but its placement action is separate. No Griess axes, VOA structure, instrument-edge identification or native motion authority is inferred.',
        'nextObligation':'Construct actual typed inter-reader/inter-instrument maps and their compositions. Preserve full-field PN geometric obstruction; do not enlarge generators solely to fit a target group.'}
sources=[Path(__file__),Path(s.__file__),Path(s.r.__file__),ROOT/'research/strominger/simplex-interface-algebra-v1.md',BASE/'rotation-realization-square/verification.json',BASE/'field-rotation-rigidity/verification.json',BASE/'common-three-carrier-protocol/proton.json']
result['sourceHashes']={p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in sources}
out=BASE/'simplex-interface-algebra';out.mkdir(exist_ok=True)
(out/'verification.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf8')
(out/'group-table.json').write_text(json.dumps({'elements':[{'permutation':g,'Lreflection':a,'Greflection':b} for g,a,b in keys],'multiplication':table},indent=2)+'\n',encoding='utf8')
print(json.dumps({k:result[k] for k in ['status','classification','projectorAlgebra','combinedGroup','monsterIdentified']}))
